head.script:
/* 프로그램ID */
scwin.pgmId = 'PGJ15BP03';

/* 파라미터 */
scwin.param;

/* 최상단(opener, parent 포함) 기준 함수 */
scwin.isMain = function() {
    return true;
};

/* 파라미터 */
scwin.schYn = "N";

/**
 * 감정평가서 onPageLoad
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2024.09.03.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 *
 */
scwin.onpageload = function() {
    scwin.param = com.data.getParameter("paramObj");

    grp_dpcnMrgCsTitle.hide(); // 중복병합사건 타이틀
    grp_grp_dpcnMrgCsCtt.hide(); // 중복병합사건 내용

    setTimeout(function(){
        pgjUtil.setPopUpCloseNextTabEvent($p.getFrame());
    }, 500);

	if (!scutilo.isEmpty(scwin.param)) {
		dma_srchAeeWevl.set("cortOfcCd",scwin.param.cortOfcCd);
        dma_srchAeeWevl.set("cortSptNm",scwin.param.cortSptNm);
		dma_srchAeeWevl.set("csNo",scwin.param.csNo);
		dma_srchAeeWevl.set("auctnInfOriginDvsCd",'4');
		dma_srchAeeWevl.set("dspslDxdyYmd",scwin.param.dxdy);
		dma_srchAeeWevl.set("pgmId",scwin.pgmId);
        com.executeSubmission(sbm_selectAeeWevlInfo);
    }
};

scwin.onpageunload = function() {

};

/**
 * 명령횟차별 감정평가서 조회후 데이터 셋팅
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2024.09.03.   나해준               [NELS]최초 생성
 *  2026.04.02.   강은숙               [26A-PGJ-0014] 현황조사서, 감정평가서 로봇차단솔루션 적용되게 개선
 *  2026.09.18.   강은숙               [26A-PGJ-0043] 감정평가서 팝업화면 안내문구 및 안내 메세지 추가
 * ============= ============ ==========================
 */
scwin.sbm_selectAeeWevlInfo_submitdone = function(e) {

    //20260402 강은숙 [26A-PGJ-0014] 현황조사서, 감정평가서 로봇차단솔루션 적용되게 개선
    const ipcheck = e.responseJSON.data.ipcheck; //로봇탐지 결과 처리
    if(ipcheck){

	    //법원사무소명
	    spn_aeeEvlCortOfcNm.setValue(scwin.param.cortSptNm);

	    //사건번호
	    spn_aeeEvlCsNo.setValue(dma_ordTsIndvdAeeWevlInf.get("userCsNo"))

	    //명령회차
	    sbx_aeeEvlOrdTs.removeAll();
	    let ordTsCnt = dma_ordTsIndvdAeeWevlInf.get("ordTsCnt");

        // 명령회차수 바인딩 //2026.09.18. 강은숙 [26A-PGJ-0043] 감정평가서 없는경우 안내 메세지 추가
        if (dlt_aeeWevlOrdTsLst.getTotalRow()>0) {

		    let idx1 = 0;
		    dlt_aeeWevlOrdTsLst.getAllJSON().forEach( (r,i) =>{
		        sbx_aeeEvlOrdTs.addItem(r.ordTsCnt, r.ordTsCnt, i);
		        if(r.ordTsCnt == ordTsCnt){
		            idx1 = i;
		        }
		    });
		    sbx_aeeEvlOrdTs.setSelectedIndex(idx1);

		    //중복,병합 사건 존재시
		    if (dlt_dpcnMrgCsLst.getTotalRow()>0) {
		        grp_dpcnMrgCsTitle.show(""); // 중복병합사건 타이틀
		        grp_grp_dpcnMrgCsCtt.show(""); // 중복병합사건 내용
		        sbx_aeeEvlDpcnMrgCs.removeAll();
		        let csNo = dma_ordTsIndvdAeeWevlInf.get("csNo");
		        let idx2 = 0;
		        dlt_dpcnMrgCsLst.getAllJSON().forEach( (r,i) =>{
		            sbx_aeeEvlDpcnMrgCs.addItem(r.reltCsNo+'_'+r.ordTsCnt, r.userRletCsNo, i);
		            if(r.reltCsNo == csNo){
		                idx2 = i;
		            }
		        });
		        sbx_aeeEvlDpcnMrgCs.setSelectedIndex(idx2);
		    }
		    scwin.schYn = "Y";

		    let cortCd = dma_ordTsIndvdAeeWevlInf.get("cortOfcCd")
		    cortCd = cortCd.replaceAll('B',"");
		    let csNo = dma_ordTsIndvdAeeWevlInf.get("csNo")
		    let aeeWevlNo = dma_ordTsIndvdAeeWevlInf.get("aeeWevlNo")
		    let wrtYmd = dma_ordTsIndvdAeeWevlInf.get("wrtYmd")
		    let url = `https://ca.kapanet.or.kr/view/${cortCd}/${csNo}/${ordTsCnt}/${aeeWevlNo}/${wrtYmd}`

		    document.getElementById('sbx_iframeTest').src = url

	    } else {
            scutilo.showMsg(scglblo.MSG.WARN,"감정평가서가 존재하지 않습니다.",()=>{
                com.win.closePopup("");
            })
        }
	} else {
        scutilo.showMsg(scglblo.MSG.ERROR,e.responseJSON.message,()=>{
            com.win.closePopup("");
        });
    }
};

/**
 * 명령회차 선택시 이벤트
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2024.09.03.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 *
 */
scwin.sbx_aeeEvlOrdTs_onchange = function(info) {
    if(scwin.schYn == "Y"){
        dma_srchAeeWevl.set("ordTsCnt", info.newValue);
        com.executeSubmission(sbm_selectAeeWevlInfo);
    }
};

/**
 * 중복/병합 사건 선택시 이벤트
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2024.09.03.   나해준                  [NELS]최초 생성
 *  2025.09.17.   강은숙                  [25A-PGJ-0027] 병합사건 감정평가서 조회 오류 개선
 * ============= ============ ==========================
 *
 */
scwin.sbx_aeeEvlDpcnMrgCs_onchange = function(info) {
    const value = info.newValue.split('_');
    /*
     * value[0] -> 사건번호
     * value[1] -> 명령회차수
     */
    const csNo = value[0];
    if (value[1]>0) {
        dma_srchAeeWevl.set("csNo", csNo);
        dma_srchAeeWevl.set("ordTsCnt", ""); // [25A-PGJ-0027] 병합사건 감정평가서 조회 오류 개선
        com.executeSubmission(sbm_selectAeeWevlInfo);
    } else {
        scutilo.showMsg(scglblo.MSG.WARN,scutilo.getMsg(pgjmsg.PGJ.W_0059,'감정평가서'));
    }
};
